    95|export function classifyTaskType(prompt: string): IVXTaskType {
    96|  const lower = prompt.toLowerCase();
    97|  const requestsImplementation = /\b(fix|repair|resolve|patch|change|update|add|create|build|implement)\b/.test(lower);
    98|  const requestsFix = /\b(fix|repair|resolve|patch)\b/.test(lower);
    99|  if (lower.includes('redeploy') || (lower.includes('deploy') && !requestsImplementation)) return 'DEPLOYMENT';
   100|  if (lower.includes('audit') || lower.includes('inspect') || lower.includes('report only') || lower.includes('explain')) return 'INVESTIGATION';
   101|  if (requestsImplementation) {
   102|    if (lower.includes('chat') || lower.includes('scroll') || lower.includes('keyboard') || lower.includes('loading') || lower.includes('ui')) return 'UI_FIX';
   103|    if (requestsFix) return 'CODE_FIX';
   104|    if (lower.includes('add') || lower.includes('create') || lower.includes('build') || lower.includes('implement')) return 'FEATURE';
   105|    return 'CODE_FIX';
   106|  }
   107|  if (lower.includes('qa') || lower.includes('verify') || lower.includes('test the')) return 'QA_ONLY';
   108|  if (lower.includes('chat') || lower.includes('scroll') || lower.includes('keyboard') || lower.includes('loading') || lower.includes('ui')) return 'UI_FIX';
   109|  return 'CODE_FIX';
